      { "id": 4, "number": 4, "title": "GÜVENLİ TAHLİYE", "timing": "Müdahale Boyunca", "color": "teal", "icon": "Wind", "text": "..." },
      { "id": 5, "number": 5, "title": "TOPLANMA VE SAYIM", "timing": "3. Dakika", "color": "indigo", "icon": "Compass", "text": "..." },
      { "id": 6, "number": 6, "title": "DEVİR TESLİM VE RAPOR", "timing": "Dış Destek", "color": "purple", "icon": "ShieldCheck", "text": "..." }
